CREATE POLICY "downloads read own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'downloads' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "downloads insert own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'downloads' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "downloads update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'downloads' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "downloads delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'downloads' AND (storage.foldername(name))[1] = auth.uid()::text);